volatile bool user_interrupt = false;

// Game state
// create the board array
// static uint8_t board[BOARD_SIZE][BOARD_SIZE];
// starting position for the selection box
int selector_r = START_POSITION_ROW;
int selector_c = START_POSITION_COLUMN;

// setup the starting positions
uint8_t board[BOARD_SIZE][BOARD_SIZE];

void init_reversi_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE])
{
    // reset the start positions for when we play an additional round
    selector_r = START_POSITION_ROW;
    selector_c = START_POSITION_COLUMN;
    // set all squares as empty
    memset((*b), EMPTY, sizeof((*b)));
    // Standard Reversi starting position
    (*b)[3][3] = WHITE;
    (*b)[3][4] = BLACK;
    (*b)[4][3] = BLACK;
    (*b)[4][4] = WHITE;
}

void init_checkers_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE])
{
    selector_r = 5;
    selector_c = 0;
    for (int r = 0; r < BOARD_SIZE - 5; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            if ((c + r) % 2 != 0)
            {
                (*b)[r][c] = BLACK;
            }
        }
    }
    for (int r = 5; r < BOARD_SIZE; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            if ((c + r) % 2 != 0)
            {
                (*b)[r][c] = RED;
            }
        }
    }
}

void init_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE], int board_type)
{
    if (board_type == REVERSI)
        init_reversi_board(b);
    else if (board_type == CHECKERS)
        init_checkers_board(b);
}

int get_piece(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE], int r, int c)
{
    return (*b)[r][c];
}

void place_piece(const uint16_t (*piece)[SPRITE_SIZE * SPRITE_SIZE], int r, int c)
{
    int x = (OFFSET_PX + CELL_SIZE * c) + 2;
    int y = (OFFSET_PX + CELL_SIZE * r) + 2;
    lcd_blit((*piece), x, y, SPRITE_SIZE, SPRITE_SIZE);
    sleep_ms(8);
}

void remove_piece(int r, int c, int board_type)
{
    switch (board_type)
    {
    case CHECKERS:
        int x = (OFFSET_PX + CELL_SIZE * c) + 1;
        int y = (OFFSET_PX + CELL_SIZE * r) + 1;
        if ((c + r) % 2 == 0)
        {
            lcd_solid_rectangle(COLOR_CREAM, x, y, CELL_SIZE, CELL_SIZE);
        }
        else
        {
            lcd_solid_rectangle(COLOR_GREEN, x, y, CELL_SIZE, CELL_SIZE);
        }
        break;
    }
}

// remove the selector box from the current location
void erase_selector(uint16_t color)
{
    int lx = CELL_SIZE * selector_c + OFFSET_PX + 2;       // left selection box bar
    int rx = CELL_SIZE * (selector_c + 1) + OFFSET_PX - 1; // right selection box bar
    int ly = CELL_SIZE * selector_r + OFFSET_PX + 2;       // top selection box bar
    int ry = CELL_SIZE * (selector_r + 1) + OFFSET_PX - 1; // bottom selection box bar
    int l = SPRITE_SIZE;                                   // selection box border bar length
    int w = 1;                                             // selection box border bar width
    lcd_solid_rectangle(color, lx, ly, w, l);              // Left
    lcd_solid_rectangle(color, lx, ly, l, w);              // Top
    lcd_solid_rectangle(color, rx, ly, w, l);              // Right
    lcd_solid_rectangle(color, lx, ry, l, w);              // Bottom
}

void draw_selector(int new_r, int new_c, uint16_t color)
{
    int lx = CELL_SIZE * new_c + OFFSET_PX + 2;       // left selection box bar
    int rx = CELL_SIZE * (new_c + 1) + OFFSET_PX - 1; // right selection box bar
    int ly = CELL_SIZE * new_r + OFFSET_PX + 2;       // top selection box bar
    int ry = CELL_SIZE * (new_r + 1) + OFFSET_PX - 1; // bottom selection box bar
    int l = SPRITE_SIZE;                              // selection box border bar length
    int w = 1;                                        // selection box border bar width
    lcd_solid_rectangle(color, lx, ly, w, l);         // Left
    lcd_solid_rectangle(color, lx, ly, l, w);         // Top
    lcd_solid_rectangle(color, rx, ly, w, l);         // Right
    lcd_solid_rectangle(color, lx, ry, l, w);         // Bottom
}

void move_selector(int new_r, int new_c, int board_type)
{
    if ((new_r < BOARD_SIZE && new_r >= 0) && (new_c < BOARD_SIZE && new_c >= 0))
    {
        if (board_type == REVERSI)
        {
            erase_selector(COLOR_GREEN);
        }
        else if (board_type == CHECKERS)
        {
            if ((selector_r + selector_c) % 2 == 0)
            {
                erase_selector(COLOR_CREAM);
            }
            else
            {
                erase_selector(COLOR_GREEN);
            }
        }
        draw_selector(new_r, new_c, COLOR_SELECTOR);
        // set new selection box position
        selector_c = new_c;
        selector_r = new_r;
    }
}

void draw_reversi_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE])
{
    int draw_delay = 0;
    lcd_solid_rectangle(COLOR_BLACK, OFFSET_PX, OFFSET_PX, BOARD_PX, BOARD_PX);
    for (int r = 0; r < BOARD_SIZE; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            int x = (OFFSET_PX + CELL_SIZE * c) + 2;
            int y = (OFFSET_PX + CELL_SIZE * r) + 2;
            lcd_solid_rectangle(COLOR_GREEN, x, y, SPRITE_SIZE, SPRITE_SIZE);
            sleep_ms(draw_delay);
        }
    }
    for (int r = 0; r < BOARD_SIZE; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            if ((*b)[r][c] == EMPTY)
                continue;
            else if ((*b)[r][c] == BLACK)
            {
                place_piece(&black_disc, r, c);
            }
            else
            {
                place_piece(&white_disc, r, c);
            }
        }
    }
}

void draw_checkers_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE])
{
    int draw_delay = 0;
    for (int r = 0; r < BOARD_SIZE; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            int x = (OFFSET_PX + CELL_SIZE * c) + 1;
            int y = (OFFSET_PX + CELL_SIZE * r) + 1;
            if ((c + r) % 2 == 0)
            {
                lcd_solid_rectangle(COLOR_CREAM, x, y, CELL_SIZE, CELL_SIZE);
            }
            else
            {
                lcd_solid_rectangle(COLOR_GREEN, x, y, CELL_SIZE, CELL_SIZE);
            }
            sleep_ms(draw_delay);
        }
    }
    for (int r = 0; r < BOARD_SIZE; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            if ((*b)[r][c] == EMPTY)
                continue;
            else if ((*b)[r][c] == BLACK)
            {
                place_piece(&blue_checker, r, c);
            }
            else
            {
                place_piece(&red_checker, r, c);
            }
        }
    }
}

void render_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE], int board_type)
{
    if (board_type == REVERSI)
        draw_reversi_board(b);
    else if (board_type == CHECKERS)
        draw_checkers_board(b);

    move_selector(selector_r, selector_c, board_type);
}

void redraw_board(uint8_t (*b)[BOARD_SIZE][BOARD_SIZE], int board_type)
{
    for (int r = 0; r < BOARD_SIZE; r++)
    {
        for (int c = 0; c < BOARD_SIZE; c++)
        {
            if ((*b)[r][c] == EMPTY)
            {
                continue;
            }
            else if ((*b)[r][c] == BLACK)
            {
                place_piece(&black_disc, r, c);
            }
            else
            {
                place_piece(&white_disc, r, c);
            }
        }
    }
    move_selector(selector_r, selector_c, board_type);
}
